<!DOCTYPE html>
<html lang="ko">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>EXAONE-3.5-32B 미디어아트</title>
    <style>
        body, html {
            margin: 0;
            padding: 0;
            width: 100%;
            height: 100%;
            overflow: hidden;
            font-family: 'Arial', sans-serif;
            background-color: #1e1e2e;
            color: #ffffff;
            display: flex;
            justify-content: center;
            align-items: center;
            text-align: center;
            scroll-behavior: smooth;
        }
        .container {
            display: flex;
            flex-direction: column;
            align-items: center;
            justify-content: center;
            width: 90%;
            max-width: 800px;
            padding: 20px;
            box-sizing: border-box;
        }
        h1 {
            font-size: 2.5em;
            margin-bottom: 10px;
            text-shadow: 0 0 10px rgba(255, 255, 255, 0.5);
        }
        .visual {
            position: relative;
            width: 100%;
            height: 300px;
            margin: 20px 0;
            background: radial-gradient(circle, #3498db, #2ecc71);
            animation: pulse 3s infinite;
            will-change: opacity; /* Respect reduced motion preference */
        }
        @media (prefers-reduced-motion: reduce) {
            .visual {
                animation: none;
                background: radial-gradient(circle, #3498db, #2ecc71); /* Still version */
            }
        }
        .visual::before {
            content: '';
            position: absolute;
            top: 0;
            left: 0;
            width: 100%;
            height: 100%;
            background: rgba(0, 0, 0, 0.2);
            border-radius: 15%;
            clip-path: polygon(50% 0%, 100% 50%, 50% 100%, 0% 50%);
            animation: moveWave 4s infinite linear;
            will-change: transform; /* Respect reduced motion preference */
        }
        @media (prefers-reduced-motion: reduce) {
            .visual::before {
                animation: none;
            }
        }
        @keyframes pulse {
            0% { opacity: 1; }
            50% { opacity: 0.5; }
            100% { opacity: 1; }
        }
        @keyframes moveWave {
            0% { transform: translateX(-100%); }
            100% { transform: translateX(100%); }
        }
        .interactive {
            margin-top: 20px;
            font-size: 1.2em;
            cursor: pointer;
            transition: color 0.3s;
            outline: none; /* Improve keyboard focus visibility */
            tabindex: 0; /* Make focusable via keyboard */
            role: button; /* Semantic role for accessibility */
        }
        .interactive:focus {
            color: #ff6347;
            outline: 2px solid #ff6347; /* Focus outline for accessibility */
        }
        .interactive:hover {
            color: #ff6347;
        }
        @media (max-width: 600px) {
            h1 {
                font-size: 2em;
            }
        }
    </style>
</head>
<body>
    <div class="container">
        <h1 id="modelName">EXAONE-3.5-32B</h1>
        <div class="visual"></div>
        <p class="interactive" tabindex="0" role="button" onclick="showInteractionMessage()" onkeydown="handleKeyPress(event)">상호작용하기</p>
    </div>
    <script>
        function showInteractionMessage() {
            const message = document.createElement('div');
            message.style.position = 'fixed';
            message.style.top = '50%';
            message.style.left = '50%';
            message.style.transform = 'translate(-50%, -50%)';
            message.style.backgroundColor = 'rgba(0, 0, 0, 0.7)';
            message.style.color = '#ffffff';
            message.style.padding = '20px';
            message.style.borderRadius = '8px';
            message.style.zIndex = '1000';
            message.textContent = 'EXAONE-3.5-32B와의 상호작용을 환영합니다!';
            document.body.appendChild(message);
            setTimeout(() => message.remove(), 3000); // Automatically remove after 3 seconds
        }

        function handleKeyPress(event) {
            if (event.key === 'Enter') {
                showInteractionMessage();
            }
        }

        // 접근성 향상을 위한 기본 설정
        document.body.style.setProperty('--text-contrast', '#ffffff'); // 글자 색상 대비 설정
        document.body.style.setProperty('--bg-color', '#1e1e2e'); // 배경 색상 설정
    </script>
</body>
</html>
